self.KB_CONTENT["card:779789"]={"id":"card:779789","ty":"card","sourceId":"779789","title":"『品號類別資料建立作業』的作業目的為何？","ver":"GP4以上","topic":"品號","keywords":["品號","類別","分類","共用"],"y":"explain","answer":"本作業乃針對「共用參數設定作業」中，定義的四種分類子項資料建立。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
