self.KB_CONTENT["card:750274"]={"id":"card:750274","ty":"card","sourceId":"750274","title":"『供應廠商資料建立作業』中的『品質評等 (PUR.MA033)』為何？","ver":"iGP","topic":"採購","keywords":["採購","廠商","供應","透過"],"y":"other","answer":"* 可自行設定或透過採購系統『廠商交貨/品質評等』來更新。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[750274,778177],"file":"kb-cards.jsonl"};
