self.KB_CONTENT["card:755677"]={"id":"card:755677","ty":"card","sourceId":"755677","title":"『暫出/入單明細表』中的『選擇預計轉銷日期 (INV.TF041)』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","暫出入","預計"],"y":"other","answer":"* 可點選(icon)或[F2]日期快手查詢暫出/入單之預計轉銷日期，若空白表全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
