self.KB_CONTENT["card:793518"]={"id":"card:793518","ty":"card","sourceId":"793518","title":"『INVOICE』中的『選擇單據日期 (TA070)』為何？","ver":"GP4以上","topic":"印出","keywords":["印出","期間"],"y":"other","answer":"* 可點選(icon)或[F2]日期快手查詢所需列印之單據日期期間。空白表所有單據日期皆需印出。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
