self.KB_CONTENT["field:791703"]={"id":"field:791703","ty":"field","sourceId":"791703","title":"選擇確認狀態","ver":"GP4以上","topic":"","keywords":[],"job":"保修退料單憑證列印","code":"TK006","answer":"* 選擇要列印何種確認狀態的保修退料資料。* 確認狀態有：已確認、未確認、作廢、全部（表示所有確認狀態都印）。","file":"fields.jsonl"};
